/*
1. COMPOSITION: 6.8x2.0 footer band plane at z=0 over a 7x6 gradient backdrop at z=-2.5; wordmark block left, three link columns right on 0.25 baseline grid, two etched hairlines, legal line at bottom.
2. LIGHT RIG: rig-gallery-soft — key #fff8f0 1.9 upper-left graze, hemisphere fill #f2eee8 0.65, rim #ffffff 0.8 behind; ambient floor 0.3.
3. MATERIALS: band = MeshStandardNodeMaterial with TSL vertical ramp #121218->#0b0b10, roughness 0.6 metalness 0.2; hairlines #23232b slightly metallic to catch the key; accent bar emissive #ff2a38 @1.4.
4. MOTION: single fade-up of whole band (opacity 0->1, y +0.2->0, 500ms power2.out); link hover paper->red 140ms + z 0->0.02. No stagger, no idle multi-axis motion.
5. FOCAL: the emissive #ff2a38 accent bar under the wordmark is the single brightest element; everything else graded below it.
*/
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'footer-colophon';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#101015',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    hairline: '#23232b',
    gradTop: colors.gradientStops?.[0]?.hex ?? '#121218',
    gradBot: colors.gradientStops?.[1]?.hex ?? '#0b0b10',
  };

  const geometries = [];
  const materials = [];
  const timelines = [];
  const primHandles = [];

  // ---------- stage backdrop (gradient, no void) ----------
  function buildBackdrop() {
    const geo = new THREE.PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();
    const t = uv().y;
    const bot = vec3(...new THREE.Color(C.background).toArray());
    const top = vec3(...new THREE.Color(C.gradTop).toArray());
    // subtle vertical grade + faint vignette lift toward center
    const lift = smoothstep(0.0, 1.0, t).mul(0.6).add(0.4);
    mat.colorNode = mix(bot, top, t.mul(lift));
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    geometries.push(geo); materials.push(mat);
    return mesh;
  }
  root.add(buildBackdrop());

  // ---------- light rig (rig-gallery-soft) ----------
  function buildLights() {
    const g = new THREE.Group();
    const r = 2.0; // subject bounding radius ~ half band diag
    const key = new THREE.DirectionalLight('#fff8f0', 1.5);
    key.position.set(0.8 * r, 3.4 * r, 2 * r);
    key.target.position.set(0, 0.5, 0);
    g.add(key, key.target);
    const fill = new THREE.HemisphereLight('#f2eee8', C.background, 0.65);
    g.add(fill);
    const rim = new THREE.DirectionalLight('#ffffff', 0.8);
    rim.position.set(0.4 * r, 1.8 * r, -2.8 * r);
    rim.target.position.set(0, 0.6, 0);
    g.add(rim, rim.target);
    const amb = new THREE.AmbientLight('#f2eee8', 0.3);
    g.add(amb);
    return g;
  }
  root.add(buildLights());

  // ---------- footer band ----------
  const band = new THREE.Group();
  band.name = 'band';
  const BW = 6.8, BH = 2.0;

  function buildBandPlate() {
    const geo = new THREE.PlaneGeometry(BW, BH);
    const mat = new MeshStandardNodeMaterial({ roughness: 0.6, metalness: 0.2 });
    const t = uv().y;
    const bot = vec3(...new THREE.Color(C.gradBot).toArray());
    const top = vec3(...new THREE.Color(C.gradTop).toArray());
    mat.colorNode = mix(bot, top, t);
    const mesh = new THREE.Mesh(geo, mat);
    geometries.push(geo); materials.push(mat);
    return mesh;
  }
  band.add(buildBandPlate());

  // hairline rules — slightly metallic so the grazing key etches them
  function makeHairline(width, y) {
    const geo = new THREE.PlaneGeometry(width, 0.006);
    const mat = new MeshStandardNodeMaterial({
      color: new THREE.Color(C.hairline),
      roughness: 0.35, metalness: 0.5,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(0, y, 0.005);
    geometries.push(geo); materials.push(mat);
    return mesh;
  }
  const hairlineTop = makeHairline(BW, BH / 2 - 0.003);
  const legalRuleY = -BH / 2 + 0.375 + 0.25; // legal 0.375 above bottom, rule 0.25 above legal
  const hairlineLegal = makeHairline(BW, legalRuleY);
  band.add(hairlineTop, hairlineLegal);

  // accent bar — the single brightest element
  function buildAccentBar() {
    const geo = new THREE.PlaneGeometry(0.3, 0.02);
    const mat = new MeshStandardNodeMaterial({
      color: new THREE.Color(C.accent),
      emissive: new THREE.Color(C.accent),
      emissiveIntensity: 1.4,
      roughness: 0.5, metalness: 0.0,
    });
    const mesh = new THREE.Mesh(geo, mat);
    geometries.push(geo); materials.push(mat);
    return mesh;
  }

  // ---------- text layout ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byIndex = (i, fallback) => items[i]?.text ?? fallback;

  const PAPER = C.paper;
  const linkMeshes = [];

  function addText(str, opts, x, y, z = 0.01) {
    const obj = ctx.fontAtlas.createText(String(str), opts);
    obj.position.set(x, y, z);
    band.add(obj);
    return obj;
  }

  // left wordmark block (left edge at -BW/2 + padding 0.5)
  const leftX = -BW / 2 + 0.5;
  function buildWordmark() {
    const wm = addText(byIndex(0, 'NOVA ATELIER'), {
      fontSize: 34, color: PAPER, align: 'left', letterSpacingPx: 0.7,
    }, leftX, 0.35);
    const bar = buildAccentBar();
    bar.position.set(leftX + 0.15, 0.35 - 0.62 / 2 - 0.15, 0.01);
    band.add(bar);
    return wm;
  }
  buildWordmark();

  // three link columns: each 1.2w, 0.375 gutters, right side
  const colW = 1.2, gutter = 0.375;
  const colsStartX = leftX + 2.0 + gutter; // wordmark block occupies left 2.0 units
  const headerY = BH / 2 - 0.45;
  const lineStep = 0.25; // baseline grid, 1.8 line-height at 13px ~ 0.25 units

  const columns = [
    { headerIdx: 1, links: [2, 3, 4], nav: ['hub-features', 'hub-collection', 'hub-pricing'] },
    { headerIdx: 5, links: [6, 7, 8], nav: ['hub-journal', 'visit', 'contact'] },
    { headerIdx: 9, links: [10, 11, 12], nav: ['privacy', 'terms', 'warranty'] },
  ];

  function buildColumns() {
    columns.forEach((col, ci) => {
      const x = colsStartX + ci * (colW + gutter);
      addText(byIndex(col.headerIdx, ''), {
        fontSize: 9, color: PAPER, align: 'left', letterSpacingPx: 1.1,
      }, x, headerY);
      col.links.forEach((li, ri) => {
        const linkText = byIndex(li, '');
        const link = addText(linkText, {
          fontSize: 13, color: PAPER, align: 'left',
        }, x, headerY - 0.3 - ri * lineStep);
        link.userData.linkId = `link-${li}`;
        link.userData.navTarget = col.nav[ri];
        linkMeshes.push(link);
      });
    });
  }
  buildColumns();

  // legal line 0.375 above bottom edge
  function buildLegal() {
    return addText(byIndex(13, '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.'), {
      fontSize: 9, color: PAPER, align: 'left', letterSpacingPx: 0.36,
    }, leftX, -BH / 2 + 0.375);
  }
  buildLegal();

  root.add(band);

  // ---------- primitives from config ----------
  for (const p of config.cinematicPrimitives ?? []) {
    const h = ctx.primitives[p.name]?.(band, p.params);
    if (h) primHandles.push(h);
  }

  // ---------- motion: single fade-up mount ----------
  band.position.y = 0.2;
  const opacityTargets = [];
  band.traverse((o) => {
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) { m.transparent = true; m.opacity = 0; opacityTargets.push(m); }
    }
  });
  const mountTl = gsap.timeline();
  mountTl.to(band.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  mountTl.to(opacityTargets, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(mountTl);

  // ---------- interactions: link hover paper -> accent, z lift ----------
  const paperColor = new THREE.Color(PAPER);
  const accentColor = new THREE.Color(C.accent);

  function setLinkColor(obj, colorHex) {
    obj.traverse((o) => {
      if (o.material && o.material.color) o.material.color.set(colorHex);
    });
  }

  function hoverLink(obj, on) {
    const tl = gsap.timeline();
    const proxy = { t: on ? 0 : 1 };
    tl.to(proxy, {
      t: on ? 1 : 0, duration: 0.14, ease: 'power2.out',
      onUpdate() {
        const c = paperColor.clone().lerp(accentColor, proxy.t);
        setLinkColor(obj, '#' + c.getHexString());
      },
    }, 0);
    tl.to(obj.position, { z: on ? 0.03 : 0.01, duration: 0.14, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  root.userData.handlers = {
    pointerover: (hit) => {
      const link = linkMeshes.find((l) => l === hit || (hit && l.children.includes(hit)) || (hit && hit.parent === l));
      if (link) hoverLink(link, true);
    },
    pointerout: (hit) => {
      const link = linkMeshes.find((l) => l === hit || (hit && l.children.includes(hit)) || (hit && hit.parent === l));
      if (link) hoverLink(link, false);
    },
    click: (hit) => {
      const link = linkMeshes.find((l) => l === hit || (hit && l.children.includes(hit)) || (hit && hit.parent === l));
      if (link && link.userData.navTarget) ctx.emit('navigate', { to: link.userData.navTarget });
    },
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primHandles) h.cleanup?.();
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of mats) { m.map?.dispose?.(); m.dispose?.(); }
      }
    });
    for (const g of geometries) g.dispose();
    for (const m of materials) m.dispose();
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.wordmark.0","where":"buildWordmark","how":"MSDF wordmark 34px left block"},
{"id":"text.column-header.1","where":"buildColumns","how":"ATELIER header col 0"},
{"id":"text.link.2","where":"buildColumns","how":"Features link col 0 row 0"},
{"id":"text.link.3","where":"buildColumns","how":"Collection link col 0 row 1"},
{"id":"text.link.4","where":"buildColumns","how":"Pricing link col 0 row 2"},
{"id":"text.column-header.5","where":"buildColumns","how":"COMPANY header col 1"},
{"id":"text.link.6","where":"buildColumns","how":"Journal link col 1 row 0"},
{"id":"text.link.7","where":"buildColumns","how":"Visit the Atelier link col 1"},
{"id":"text.link.8","where":"buildColumns","how":"Contact link col 1 row 2"},
{"id":"text.column-header.9","where":"buildColumns","how":"LEGAL header col 2"},
{"id":"text.link.10","where":"buildColumns","how":"Privacy link col 2 row 0"},
{"id":"text.link.11","where":"buildColumns","how":"Terms link col 2 row 1"},
{"id":"text.link.12","where":"buildColumns","how":"Warranty link col 2 row 2"},
{"id":"text.legal.13","where":"buildLegal","how":"legal line above bottom edge"},
{"id":"color.background","where":"buildBackdrop","how":"backdrop gradient bottom stop"},
{"id":"color.surface","where":"buildBandPlate","how":"band surface tones via gradient"},
{"id":"color.ink","where":"buildLights","how":"hemisphere ground tint uses ink-family bg"},
{"id":"color.paper","where":"buildColumns","how":"all text rendered paper #e8ecf2"},
{"id":"color.accent","where":"buildAccentBar","how":"emissive red bar plus hover lerp"},
{"id":"color.gradient","where":"buildBandPlate","how":"TSL vertical ramp 121218 to 0b0b10"},
